using System;using System.IO;using System.Drawing;using System.Reflection;using System.Windows.Forms;using EanEtikety;
class WorkspaceUiTests {
 static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;static string dir;static int count;
 static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,flags).Invoke(o,args);}
 static T Field<T>(object o,string name){return (T)o.GetType().GetField(name,flags).GetValue(o);}
 static void Check(bool value,string message){count++;if(!value)throw new Exception(message);}
 static Button FindButton(Control c,string text){if(c is Button&&c.Text==text)return (Button)c;foreach(Control child in c.Controls){var found=FindButton(child,text);if(found!=null)return found;}return null;}
 static void Dialog(MainForm main,string method,string name){bool seen=false;Exception error=null;using(var timer=new Timer{Interval=120}){timer.Tick+=delegate{foreach(Form form in Application.OpenForms)if(form!=main&&form.Visible){timer.Stop();seen=true;try{form.Location=new Point(-20000,-20000);Application.DoEvents();if(method=="ShowBatch"){var prepare=FindButton(form,Loc.T("Pripraviť dávku"));Check(prepare!=null,"prepare batch action");prepare.PerformClick();Application.DoEvents();}Check(form.Font.Name=="Source Sans 3",name+" font");Check(form.ShowIcon&&form.Icon!=null,name+" logo");using(var b=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,name+".png"));}}catch(Exception ex){error=ex;}finally{form.Close();}break;}};timer.Start();Call(main,method);}Check(seen,name+" opened");if(error!=null)throw error;}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var main=new MainForm(Path.Combine(dir,"prefs.xml"))){main.StartPosition=FormStartPosition.Manual;main.Location=new Point(-20000,-20000);main.Show();foreach(string lang in Loc.Codes){Loc.Language=lang;Call(main,"ApplyTheme");foreach(string method in new[]{"ShowBatch","EditVariables","EditSheet","ShowLibrary","RecoveryPreferences","ShowArrange","ShowChecks"})Dialog(main,method,lang+"-"+method);}
 Loc.Language="sk";Call(main,"ToggleTheme");Dialog(main,"ShowBatch","light-batch");Dialog(main,"EditSheet","light-sheet");var bad=LabelSettings.Default();bad.Ean="invalid";Call(main,"Apply",bad);var preview=Field<PreviewPanel>(main,"preview");Check(preview.Settings!=null,"invalid barcode still editable");Check(preview.Scene.Shapes.Count>0,"valid text still visible");Check(preview.ProblemElements.Contains(-1),"invalid barcode highlighted");preview.SelectElement(-1);Check(preview.Element(-1)!=null,"invalid code has editable geometry");Check(!Field<Button>(main,"pdf").Enabled,"invalid barcode blocks export");Call(main,"Apply",LabelSettings.Default());main.Close();}
 File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS "+count+" dialog/font/theme/language/error continuity checks. Real monitor DPI remains manual.");}catch(Exception ex){File.WriteAllText(Path.Combine(dir,"failed.txt"),ex.ToString());Environment.ExitCode=1;}}
}
